public class Clamp {
public static int clamp(int value, int min, int max)
    {
        final int fixed;
        if (value < min)
        {
            fixed = min;
        }
        else if (value > max)
        {
            fixed = max;
        }
        else
        {
            fixed = value;
        }
        return fixed;
    }
}

Test Case:
@Test
    void testClamp()
    {
        assertEquals(0, UtilMath.clamp(-10, 0, 10));
        assertEquals(10, UtilMath.clamp(50, 0, 10));
        assertEquals(10, UtilMath.clamp(10, 0, 10));
        assertEquals(0, UtilMath.clamp(0, 0, 10));

        assertEquals(0L, UtilMath.clamp(-10L, 0L, 10L));
        assertEquals(10L, UtilMath.clamp(50L, 0L, 10L));
        assertEquals(10L, UtilMath.clamp(10L, 0L, 10L));
        assertEquals(0L, UtilMath.clamp(0L, 0L, 10L));

        assertEquals(0.0, UtilMath.clamp(-10.0, 0.0, 10.0));
        assertEquals(10.0, UtilMath.clamp(50.0, 0.0, 10.0));
        assertEquals(10.0, UtilMath.clamp(10.0, 0.0, 10.0));
        assertEquals(0.0, UtilMath.clamp(0.0, 0.0, 10.0));
    }

JUnit_jqf:
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class ClampTest {

    @Test
    public void testClamp1() {
        assertEquals(795356204, Clamp.clamp(795356204, -84439576, 542356853));
    }

    @Test
    public void testClamp2() {
        assertEquals(0, Clamp.clamp(0, 0, 0));
    }

    @Test
    public void testClamp3() {
        assertEquals(-94696591, Clamp.clamp(-714593236, -94696591, 1925915776));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testClampMinGreaterThanMax() {
        Clamp.clamp(0, 1, 0); 
    }

    @Test
    public void testClampIntegerOverflow(){
        assertEquals(Integer.MAX_VALUE, Clamp.clamp(Integer.MAX_VALUE + 1, 0, Integer.MAX_VALUE));
    }

    @Test
    public void testClampIntegerUnderflow(){
        assertEquals(Integer.MIN_VALUE, Clamp.clamp(Integer.MIN_VALUE -1, Integer.MIN_VALUE, 0));
    }

}
